--
-- Table structure for table `datos_empleado`
--

DROP TABLE IF EXISTS `datos_empleado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `datos_empleado` (
  `id_empleado` int(11) NOT NULL AUTO_INCREMENT COMMENT 'clave principal',
  `codigo_empleado` varchar(10) NOT NULL COMMENT 'Codigo de Empleado',
  `cod_datos` int(11) NOT NULL,
  `ubicacion` varchar(50) NOT NULL DEFAULT '' COMMENT 'Ubicacion donde Labora',
  `cod_cargo` int(11) NOT NULL COMMENT 'cargo que Desempeña',
  `cod_geren` int(11) NOT NULL COMMENT 'Gerencia donde Labora',
  `cod_dpto` int(11) DEFAULT NULL COMMENT 'Departamento donde Labora',
  `piso` varchar(20) NOT NULL DEFAULT '' COMMENT 'Piso donde Labora',
  `correo` varchar(100) NOT NULL DEFAULT '' COMMENT 'correo Institucional',
  `extension` bigint(20) NOT NULL COMMENT 'Numero de la Extencion',
  `Telefono` varchar(20) NOT NULL DEFAULT '' COMMENT 'Telefono Celular',
  `username` varchar(20) NOT NULL DEFAULT '',
  PRIMARY KEY (`id_empleado`),
  KEY `datos_empresa_fk` (`cod_geren`),
  KEY `datos_empresa_fk1` (`cod_dpto`),
  KEY `cod_cargo` (`cod_cargo`),
  KEY `cod_datos` (`cod_datos`),
  CONSTRAINT `datos_empleado_fk` FOREIGN KEY (`cod_cargo`) REFERENCES `cargos` (`cod_cargo`),
  CONSTRAINT `datos_empleado_fk1` FOREIGN KEY (`cod_datos`) REFERENCES `datos_personales` (`cod_datos`)
) ENGINE=InnoDB AUTO_INCREMENT=3262 DEFAULT CHARSET=utf8 COMMENT='InnoDB free: 10240 kB; (`cod_datos`) REFER `actualizacion_pr; InnoDB free: 9216 ';
/*!40101 SET character_set_client = @saved_cs_client */;

