--
-- Table structure for table `datos_personales`
--

DROP TABLE IF EXISTS `datos_personales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `datos_personales` (
  `cod_datos` int(11) NOT NULL AUTO_INCREMENT,
  `cedula` int(11) NOT NULL COMMENT 'Cedula de Identidad',
  `nombres` varchar(50) CHARACTER SET latin1 NOT NULL DEFAULT '' COMMENT 'Primer Nombre',
  `apellidos` varchar(50) CHARACTER SET latin1 NOT NULL DEFAULT '' COMMENT 'Primer Apellido',
  `fechanac` date DEFAULT NULL COMMENT 'Fecha de Nacimiento',
  `cod_civil` int(11) DEFAULT NULL COMMENT 'Codigo del Estado Civil',
  `cod_nivel` int(11) DEFAULT NULL COMMENT 'Codigo del Nivel de Instruccion',
  `cod_prof` int(11) DEFAULT NULL COMMENT 'Codigo de laProfesion',
  `cod_estado` int(11) DEFAULT NULL COMMENT 'Codigo del Estado Geografico',
  `cod_municipio` int(11) DEFAULT NULL COMMENT 'Codigo del Municipio',
  `cod_parroquia` int(11) DEFAULT NULL COMMENT 'Codigo de la Parroquia',
  `urbanizacion` varchar(250) CHARACTER SET latin1 DEFAULT NULL COMMENT 'Nombre de la Urbanizacion',
  `num_casa_apt` varchar(50) CHARACTER SET latin1 DEFAULT NULL COMMENT 'Numero de la Casa o Apartamento',
  `av_calle` varchar(70) CHARACTER SET latin1 DEFAULT NULL COMMENT 'Nombre de la Avenida o Calle',
  `referencia` varchar(256) CHARACTER SET latin1 DEFAULT NULL COMMENT 'Punto de referencia de la habitaci',
  `cod_nacion` int(11) NOT NULL COMMENT 'codigo de la nacionalidad',
  `sexo` varchar(11) DEFAULT NULL COMMENT 'Sexo de la Persona',
  `naturalidad` char(1) DEFAULT NULL,
  PRIMARY KEY (`cod_datos`),
  KEY `apellidos` (`apellidos`),
  KEY `nombres` (`nombres`),
  KEY `nivel_instruccion` (`cod_nivel`),
  KEY `profesion` (`cod_prof`),
  KEY `cod_nacion` (`cod_nacion`),
  KEY `cod_estado` (`cod_estado`),
  KEY `cod_municipio` (`cod_municipio`),
  KEY `cod_parroquia` (`cod_parroquia`),
  KEY `cod_civil` (`cod_civil`),
  CONSTRAINT `datos_personales_fk` FOREIGN KEY (`cod_prof`) REFERENCES `profesion` (`cod_prof`),
  CONSTRAINT `datos_personales_fk1` FOREIGN KEY (`cod_nacion`) REFERENCES `nacion` (`cod_nacion`),
  CONSTRAINT `datos_personales_fk2` FOREIGN KEY (`cod_nivel`) REFERENCES `nivel_instruccion` (`cod_nivel`),
  CONSTRAINT `datos_personales_fk3` FOREIGN KEY (`cod_civil`) REFERENCES `estadocivil` (`cod_civil`),
  CONSTRAINT `datos_personales_fk4` FOREIGN KEY (`cod_parroquia`) REFERENCES `parroquia` (`cod_parroquia`),
  CONSTRAINT `datos_personales_fk5` FOREIGN KEY (`cod_municipio`) REFERENCES `municipio` (`cod_municipio`),
  CONSTRAINT `datos_personales_fk6` FOREIGN KEY (`cod_estado`) REFERENCES `estado` (`cod_estado`)
) ENGINE=InnoDB AUTO_INCREMENT=4125 DEFAULT CHARSET=utf8   COMMENT='InnoDB free: 10240 kB; (`cod_estado`) REFER `actualizacion_p; InnoDB free: 9216 ';
/*!40101 SET character_set_client = @saved_cs_client */;

