//intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2025/09/1000446535.jpg,http://intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2025/09/1000446537.jpg,http://intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2025/09/1000446536.jpg\"]','#Entérate  // Desde el Centro Empresarial Horizonte S.A., se llevó a cabo el Programa de Estudios Avanzados contra la Legitimación de Capitales y el Financiamiento al Terrorismo (P.R.E.A) Cohorte XX','','inherit','closed','closed','','12850-revision-v1','','','2025-09-02 00:35:00','2025-09-02 00:35:00','',12850,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/?p=12855',0,'revision','',0),(12857,1,'2025-11-28 14:22:22','2025-11-28 14:22:22','','instragram-icon','','inherit','open','closed','','instragram-icon','','','2025-11-28 14:22:22','2025-11-28 14:22:22','',0,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2025/11/instragram-icon.jpg',0,'attachment','image/jpeg',0),(12858,1,'2025-11-28 15:06:48','2025-11-28 15:06:48','','imagen_2025-11-28_110646956','','inherit','open','closed','','imagen_2025-11-28_110646956','','','2025-11-28 15:06:48','2025-11-28 15:06:48','',0,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2025/11/imagen_2025-11-28_110646956.png',0,'attachment','image/png',0),(12921,1,'2026-01-09 17:45:01','2026-01-09 17:45:01','','icono de cumpleaño','','inherit','open','closed','','icono-de-cumpleano','','','2026-01-09 17:45:01','2026-01-09 17:45:01','',0,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/wp-content/uploads/2026/01/icono-de-cumplea--o.png',0,'attachment','image/png',0),(12923,1,'2026-01-30 16:53:18','2026-01-30 16:53:18','','Planilla ISLR','','inherit','closed','closed','','10-autosave-v1','','','2026-01-30 16:53:18','2026-01-30 16:53:18','',10,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/?p=12923',0,'revision','',0),(12926,1,'2026-02-20 13:29:09','2026-02-20 13:29:09','<?php /** Template Name: Directorio Autogestion */ ?>\r\n\r\n<?php get_header(); ?>\r\n\r\n<?php\r\n// --- 1. DEFINICIÓN DE LA CLASE DE CONEXIÓN ---\r\n// Se define dentro del archivo para asegurar que esté disponible\r\nif (!class_exists(\'conect\')) {\r\n    class conect {\r\n        private $conexion;\r\n\r\n        private function Conectarse() {\r\n            // Variables de conexión (ajusta según tu necesidad)\r\n            $dbhost = \"localhost\";\r\n            $dbusuario = \"root\";\r\n            $dbpassword = \"\";\r\n            $db = \"intranetwp\";\r\n\r\n            $this->conexion = @mysql_connect($dbhost, $dbusuario, $dbpassword);\r\n            if (!$this->conexion) {\r\n                return false;\r\n            }\r\n            mysql_select_db($db, $this->conexion);\r\n            return true;\r\n        }\r\n\r\n        public function buscarInfoEmpleado($ci) {\r\n            if (!$this->Conectarse()) return false;\r\n            \r\n            // Limpiamos la variable para evitar errores de SQL\r\n            $ci = preg_replace(\'/[^0-9]/\', \'\', $ci); \r\n            if (empty($ci)) return false;\r\n\r\n            $query = \"SELECT \r\n                        de.codigo_empleado, de.ubicacion, de.piso, de.correo, de.extension, de.Telefono,\r\n                        d.desc_dpto, c.desc_cargo, g.desc_geren,\r\n                        dp.cedula, dp.nombres, dp.apellidos,\r\n                        prof.desc_prof, ec.desc_civil\r\n                      FROM datos_empleado de\r\n                      INNER JOIN datos_personales dp ON (de.cod_datos = dp.cod_datos)\r\n                      INNER JOIN cargos c ON (de.cod_cargo = c.cod_cargo)\r\n                      INNER JOIN gerencia g ON (de.cod_geren = g.cod_geren)\r\n                      INNER JOIN departamento d ON (de.cod_dpto = d.cod_dpto)\r\n                      INNER JOIN profesion prof ON (dp.cod_prof = prof.cod_prof)\r\n                      INNER JOIN estadocivil ec ON (dp.cod_civil = ec.cod_civil)\r\n                      WHERE dp.cedula = \'$ci\' LIMIT 1\";\r\n                \r\n            $result = mysql_query($query);\r\n            return $result;\r\n        }\r\n    }\r\n}\r\n\r\n// --- 2. LÓGICA DE SESIÓN Y DATOS ---\r\nif (!session_id()) { @session_start(); }\r\n\r\n$user_ID = get_current_user_id();\r\n$info_empleado = null;\r\n\r\nif ($user_ID > 0) {\r\n    $user_data = get_user_by(\'id\', $user_ID);\r\n    // Usamos el login de WP para buscar en tu tabla (si el login es la cédula)\r\n    // Si tu login no es la cédula, cambia $user_data->user_login por la variable correcta\r\n    $_SESSION[\'usuario\'] = $user_data->user_login; \r\n    \r\n    $objCon = new conect();\r\n    $res = $objCon->buscarInfoEmpleado($_SESSION[\'usuario\']);\r\n    \r\n    if ($res && mysql_num_rows($res) > 0) {\r\n        $info_empleado = mysql_fetch_assoc($res);\r\n    }\r\n}\r\n?>\r\n\r\n<div class=\"container my-5\">\r\n    <div class=\"row\">\r\n        <div class=\"col-md-12\">\r\n            <h2 class=\"title gray\"><?php the_title(); ?></h2>\r\n            <hr>\r\n\r\n            <?php if ($user_ID == 0) : ?>\r\n                <div class=\"alert alert-info\">\r\n                    <strong>Aviso:</strong> PARA USAR ESTE SERVICIO USTED DEBE INICIAR SESION EN LA INTRANET.\r\n                </div>\r\n            <?php elseif (!$info_empleado) : ?>\r\n                <div class=\"alert alert-warning\">\r\n                    No se encontró información vinculada a su número de cédula (<?php echo $_SESSION[\'usuario\']; ?>).\r\n                </div>\r\n            <?php else : ?>\r\n                \r\n                <div class=\"panel-empleado\" style=\"background:#fff; border:1px solid #ddd; padding:25px; border-radius:10px; box-shadow: 0px 4px 10px rgba(0,0,0,0.05);\">\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-4 text-center\" style=\"border-right: 1px solid #eee;\">\r\n                            <img src=\"https://ui-avatars.com/api/?name=<?php echo $info_empleado[\'nombres\'].\'+\'.$info_empleado[\'apellidos\']; ?>&size=150&background=007bff&color=fff\" class=\"img-circle\" style=\"border-radius:50%; margin-bottom:15px;\">\r\n                            <h3 style=\"margin-bottom:5px;\"><?php echo $info_empleado[\'nombres\'] . \' \' . $info_empleado[\'apellidos\']; ?></h3>\r\n                            <span class=\"label label-primary\" style=\"background:#007bff; padding:5px 10px; border-radius:4px; color:#fff;\"><?php echo $info_empleado[\'desc_cargo\']; ?></span>\r\n                        </div>\r\n                        \r\n                        <div class=\"col-md-8\">\r\n                            <h4 style=\"color:#007bff; border-bottom:1px solid #eee; padding-bottom:10px;\">Datos de Ubicación y Contacto</h4>\r\n                            <table class=\"table\" style=\"margin-top:15px;\">\r\n                                <tbody>\r\n                                    <tr>\r\n                                        <td><strong>Gerencia:</strong></td>\r\n                                        <td><?php echo $info_empleado[\'desc_geren\']; ?></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <td><strong>Departamento:</strong></td>\r\n                                        <td><?php echo $info_empleado[\'desc_dpto\']; ?></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <td><strong>Correo Institucional:</strong></td>\r\n                                        <td><?php echo $info_empleado[\'correo\']; ?></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <td><strong>Extensión / Teléfono:</strong></td>\r\n                                        <td><?php echo $info_empleado[\'extension\']; ?> / <?php echo $info_empleado[\'Telefono\']; ?></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <td><strong>Ubicación Física:</strong></td>\r\n                                        <td><?php echo $info_empleado[\'ubicacion\']; ?> - Piso <?php echo $info_empleado[\'piso\']; ?></td>\r\n                                    </tr>\r\n                                </tbody>\r\n                            </table>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            <?php endif; ?>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<?php get_footer(); ?>','Autogestión de Identidad','','inherit','closed','closed','','14-revision-v1','','','2026-02-20 13:29:09','2026-02-20 13:29:09','',14,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/?p=12926',0,'revision','',0),(12928,1,'2026-02-20 13:30:05','2026-02-20 13:30:05','','Autogestión de Identidad','','inherit','closed','closed','','14-revision-v1','','','2026-02-20 13:30:05','2026-02-20 13:30:05','',14,'http://intrahorizonte.seguroshorizonte.com/intrahorizonte/?p=12928',0,'revision','',0),(12929,1,'2026-02-20 19:15:08','2026-02-20 19:15:08','				$mysqli = new mysqli(\"localhost\", \"root\", \"rootweb\", \"intranetwp\");\r\n		if ($mysqli->connect_errno) {\r\n		    echo \"Fallo al conectar a MySQL: (\" . $mysqli->connect_errno . \") \" . $mysqli->connect_error;\r\n		}\r\n\r\n		$mysqli->set_charset(\"utf8\");\r\n		\r\n\r\n$mysqli->real_query(\"SELECT * FROM departamento WHERE cod_geren=\'$gerencia\'\");\r\n$resultado = $mysqli->use_result();\r\n\r\n?>\r\n<label for=\"departamento\" class=\"label-control\">Departamento</label>\r\n<select id=\"departamento\" name=\"departamento\" class=\"form-control\">\r\n	<option>-Seleccione-</option><?php\r\n	while ($fila = $resultado->fetch_assoc()) {?>\r\n	<option value=\"<?php echo $fila[\"cod_dpto\"] ?>\"><?php echo $fi